import{_ as t,o as a,c as s,a4 as r}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"ADR-0052 — Sauvegarde nocturne par un service de la pile, sans attendre la commande teuthis","description":"Extrait de docs/adr/0052-sauvegarde-nocturne-par-la-pile.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0052 — Sauvegarde nocturne par un service de la pile, sans attendre la commande teuthis","description":"Extrait de docs/adr/0052-sauvegarde-nocturne-par-la-pile.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0052-sauvegarde-nocturne-par-la-pile.md","filePath":"developpeurs/adr/0052-sauvegarde-nocturne-par-la-pile.md"}'),o={name:"developpeurs/adr/0052-sauvegarde-nocturne-par-la-pile.md"};function n(d,e,i,l,c,u){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0052--sauvegarde-nocturne-par-un-service-de-la-pile-sans-attendre-la-commande-teuthis" tabindex="-1">ADR-0052 — Sauvegarde nocturne par un service de la pile, sans attendre la commande <code>teuthis</code> <a class="header-anchor" href="#adr-0052--sauvegarde-nocturne-par-un-service-de-la-pile-sans-attendre-la-commande-teuthis" aria-label="Permalink to &quot;ADR-0052 — Sauvegarde nocturne par un service de la pile, sans attendre la commande `teuthis` {#adr-0052--sauvegarde-nocturne-par-un-service-de-la-pile-sans-attendre-la-commande-teuthis}&quot;">​</a></h1><p><strong>Date :</strong> 26 septembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 26 septembre 2026, constat EXP-1 (élevé) ; amende l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a> (décisions n°4 et n°6) sur le moyen, pas sur le but</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0045 prévoit une sauvegarde <strong>nocturne</strong> de la base, des médias, des fichiers liés à une personne et du <code>.env</code>. Elle doit rester sur le serveur en v1, et sa restauration doit être <strong>testée en CI</strong>. Elle en confie l&#39;exécution à la commande <code>teuthis sauvegarder</code>, qui n&#39;existe pas encore.</p><p>L&#39;installateur (<code>deploy/installer.sh</code>) met pourtant déjà des instances en service. L&#39;audit relève (EXP-1) qu&#39;aucune ne se sauvegarde. <code>deploy/LISEZMOI.md</code> se contentait de conseiller de « sauvegarder <code>donnees-postgres</code> » : une copie à chaud de ce volume donne une base incohérente, et rien n&#39;en rappelle la nécessité.</p><p>Le Product Owner a tranché : la sauvegarde nocturne est mise en place <strong>tout de suite</strong>, par une tâche planifiée de la pile, sans attendre la commande <code>teuthis</code>.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><ol><li><p><strong>Un service <code>sauvegarde</code> dans <code>deploy/compose.yml</code></strong>, démarré avec le reste de la pile, sans profil ni réglage à renseigner.</p><ul><li>Il utilise <strong>l&#39;image PostgreSQL de la pile</strong>, épinglée par empreinte : <code>pg_dump</code> y a la version majeure du serveur, et aucune nouvelle image n&#39;entre dans la pile.</li><li>Il exécute <code>deploy/sauvegarde.sh</code> (POSIX sh, shellcheck), livré dans l&#39;archive de la pile comme les autres fichiers.</li></ul></li><li><p><strong>Chaque nuit, à <code>TEUTHIS_SAUVEGARDE_HEURE</code> (02:30, fuseau <code>TEUTHIS_FUSEAU</code>, Europe/Paris par défaut)</strong>, un dossier daté est écrit dans <code>TEUTHIS_DOSSIER_SAUVEGARDES</code> (<code>./sauvegardes</code> par défaut). Il contient :</p><ul><li><code>base.dump</code> : <code>pg_dump --format=custom</code>, une copie cohérente prise dans une transaction, relue par <code>pg_restore --list</code> avant d&#39;être retenue ;</li><li><code>fichiers.tar.gz</code> : le volume <code>donnees-api</code> (médiathèque et fichiers liés à une personne) ;</li><li><code>pile.tar.gz</code> : le dossier de la pile, <code>.env</code> compris ;</li><li><code>SHA256SUMS</code>.</li></ul><p>Tout s&#39;écrit en mode <code>umask 077</code>, lisible par root seul, puisque les copies portent des données personnelles et des secrets.</p></li><li><p><strong>Une copie n&#39;existe que complète.</strong> Elle s&#39;écrit dans <code>.en-cours-…</code>, puis est renommée quand tout a réussi. L&#39;élagage, qui ne garde que les <code>TEUTHIS_SAUVEGARDE_CONSERVATION</code> plus récentes (7 par défaut), suit une réussite, <strong>jamais un échec</strong> : une panne n&#39;efface jamais la dernière bonne copie.</p></li><li><p><strong>Un échec se voit.</strong> Il est écrit dans <code>DERNIER-ECHEC.txt</code> et journalisé, et le service passe en <code>unhealthy</code>, comme en l&#39;absence de réussite depuis 26 heures. La nuit suivante réessaie. Un réglage illisible arrête le service au démarrage (ADR-0027).</p></li><li><p><strong>La restauration est une commande du même script</strong> : <code>sh /pile/sauvegarde.sh restaurer &lt;nom&gt;</code>. Elle vérifie les sommes, refuse de tourner si une connexion est ouverte sur la base, extrait les fichiers à côté, puis restaure la base en <strong>une seule transaction</strong> avant de remplacer les fichiers. Une copie altérée ou une erreur en cours de route laisse tout en l&#39;état.</p></li><li><p><strong>La restauration est testée en CI</strong> (job <code>sauvegarde</code>, <code>.github/scripts/verifier-sauvegarde.sh</code>). Le job fait une vraie sauvegarde et une vraie restauration, qui rendent la base et les fichiers à l&#39;identique. Il vérifie aussi le refus d&#39;une copie altérée, l&#39;élagage, un échec visible sans perte, et le refus d&#39;une heure illisible.</p></li><li><p><strong>La copie reste sur le serveur</strong> (ADR-0045, D10). Le journal de chaque sauvegarde, le récapitulatif de l&#39;installateur et <code>deploy/LISEZMOI.md</code> le rappellent.</p></li></ol><p>La future commande <code>teuthis sauvegarder</code>/<code>restaurer</code> <strong>appellera ce service</strong> au lieu de le remplacer : la décision n°4 de l&#39;ADR-0045 reste valable pour l&#39;interface, et celle-ci en fournit le moteur.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Attendre <code>teuthis sauvegarder</code></strong></td><td>Les instances déjà installées resteraient sans aucune sauvegarde, ce qui est exactement le constat de l&#39;audit.</td></tr><tr><td><strong><code>cron</code> de l&#39;hôte, posé par l&#39;installateur</strong></td><td>Il se trouve hors de la pile : il est invisible dans <code>docker compose ps</code>, ne suit pas une installation manuelle, et chaque système le gère à sa façon. Un service de la pile se voit, a une santé et suit <code>docker compose up</code>.</td></tr><tr><td><strong>Tâche de l&#39;ordonnanceur de l&#39;API</strong></td><td>L&#39;image de l&#39;API n&#39;a pas <code>pg_dump</code>, et y ajouter le client PostgreSQL alourdirait les deux rôles. Il faudrait aussi monter le <code>.env</code> et les dossiers de l&#39;hôte dans l&#39;application, ce qui élargit ce qu&#39;elle peut lire.</td></tr><tr><td><strong>Image dédiée (<code>prodrigestivill/postgres-backup-local</code>…)</strong></td><td>Elle ajoute une image tierce à épingler et à surveiller, n&#39;emporte ni les fichiers ni le <code>.env</code>, et ne fournit pas de restauration testée.</td></tr><tr><td><strong>Copie du volume <code>donnees-postgres</code></strong></td><td>Elle est incohérente à chaud et suppose d&#39;arrêter la base.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Toute instance, installée par l&#39;installateur ou à la main, se sauvegarde chaque nuit dès son démarrage, sans rien renseigner.</li><li>La restauration est éprouvée à chaque modification, en CI.</li></ul><p><strong>Négatives</strong></p><ul><li>Le service <code>sauvegarde</code> détient le mot de passe de la base (comme <code>cms-api</code>) et monte <code>donnees-api</code> en écriture, ce qu&#39;exige la restauration. Il n&#39;a ni port publié ni rôle réseau.</li><li>Les copies s&#39;accumulent sur le même disque : sept jours de base et de médias. L&#39;installateur exige déjà 20 Go libres, « sauvegardes » comprises. Une médiathèque volumineuse demandera de réduire <code>TEUTHIS_SAUVEGARDE_CONSERVATION</code> ou de monter un autre disque sur <code>TEUTHIS_DOSSIER_SAUVEGARDES</code>.</li><li><strong>Une perte du serveur emporte encore les sauvegardes</strong>, jusqu&#39;à la copie distante guidée (ADR-0045, action ouverte).</li><li>Le fichier de sauvegarde de la base n&#39;est pas chiffré au repos : il dépend des droits du dossier (700, root). Le chiffrement viendra avec la copie distante, qui sort du serveur.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Service <code>sauvegarde</code>, script de sauvegarde et de restauration, documentation — <code>deploy/compose.yml</code>, <code>deploy/sauvegarde.sh</code>, <code>deploy/.env.exemple</code>, <code>deploy/LISEZMOI.md</code> (« Sauvegarde et restauration ») ; livré avec l&#39;archive de la pile (<code>publication-images.yml</code>, <code>copier_pile</code> de <code>deploy/installer.sh</code>), attendu en bonne santé par l&#39;installateur ; recette <code>.github/scripts/verifier-sauvegarde.sh</code> (job <code>sauvegarde</code> de la CI).</li></ul>',18)])])}const m=t(o,[["render",n]]);export{g as __pageData,m as default};
